stylesheet:
@font-face {
  font-family: 'Montserrat';
  font-style: normal;
  font-weight: 400 900;
  font-display: swap;
  src: url(/fonts/montserrat-latin-ext.woff2) format('woff2');
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
@font-face {
  font-family: 'Montserrat';
  font-style: normal;
  font-weight: 400 900;
  font-display: swap;
  src: url(/fonts/montserrat-latin.woff2) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

:root {
  --gs-bg:            #121212;   
  --gs-bg-deep:       #0c0e0c;
  --gs-bg-card:       #23282500; 
  --gs-card:          rgba(255,255,255,0.035);
  --gs-card-hover:    rgba(200,255,0,0.05);
  --gs-glass:         rgba(30,38,32,0.55);
  --gs-accent:        #c8ff00;   
  --gs-lime:          #c8ff00;
  --gs-accent-dim:    rgba(200,255,0,0.10);
  --gs-accent-glow:   rgba(200,255,0,0.22);
  --gs-accent-soft:   rgba(200,255,0,0.05);
  --gs-accent-mid:    rgba(200,255,0,0.40);
  --gs-emerald:       #1b5039;
  --gs-emerald-wash:  rgba(27,80,57,.07);
  --gs-emerald-deep:  #0e3122;
  --gs-light-bg:      #f4f2e9;
  --gs-logo-surface:  #fff;
  --gs-light-muted:   #303a32;
  --gs-light-faint:   #404a42;
  --gs-teal:          #4ecdc4;
  --gs-warning:       #ffc800;   
  --gs-success:       #4ecdc4;   
  --gs-danger:        #ff6b6b;   
  --gs-light-error-text: #802222;
  --gs-light-error-bg: #fff0ed;
  --gs-text:          #f5f5f5;
  --gs-text-muted:    #c4c8c1;   
  --gs-text-faint:    #9ca29b;   
  --gs-border:        rgba(200,255,0,0.10);
  --gs-border-soft:   rgba(255,255,255,0.07);
  --gs-border-strong: rgba(200,255,0,0.18);  
  --gs-ease:          cubic-bezier(0.16,1,0.3,1);
  --gs-ease-inout:    cubic-bezier(0.65,0,0.35,1);
  --gs-dur:           300ms;
  --gs-dur-micro:     150ms;   
  --gs-dur-standard:  300ms;   
  --gs-maxw:          1180px;
  --gs-gutter:        clamp(20px, 5vw, 64px);
  --gs-card-radius:   24px;
  --gs-feature-radius:48px;
  --gs-section-space:clamp(80px,10vw,144px);
}
* { margin:0; padding:0; box-sizing:border-box; }
html { scroll-behavior:smooth; -webkit-text-size-adjust:100%; }
body {
  font-family:'Montserrat',-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  background:
    radial-gradient(1100px 760px at 78% -8%, rgba(27,80,57,0.30), transparent 62%),
    radial-gradient(900px 680px at 6% 108%, rgba(14,49,34,0.40), transparent 58%),
    radial-gradient(700px 700px at 50% 40%, rgba(18,30,24,0.5), transparent 70%),
    var(--gs-bg);
  background-attachment: fixed, fixed, fixed, scroll;
  color:var(--gs-text); line-height:1.6; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
a { color:inherit; text-decoration:none; }
img { max-width:100%; display:block; }
::selection { background:var(--gs-accent); color:#0e1611; }

a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible,
[tabindex="0"]:focus-visible, [role="button"]:focus-visible, summary:focus-visible {
  outline:2px solid var(--gs-accent); outline-offset:2px;
}

h1,h2,h3 { font-weight:800; line-height:1.04; letter-spacing:-0.02em; }
.display { font-weight:900; font-size:clamp(2.6rem,7vw,6rem); line-height:0.98; letter-spacing:-0.03em; }
.h2 { font-size:clamp(2rem,4.5vw,3.6rem); }
.h3 { font-size:clamp(1.3rem,2.4vw,2rem); }
.accent { color:var(--gs-accent); }

.gs-rt-c-accent { color:var(--gs-accent); }
.gs-rt-c-teal   { color:var(--gs-teal); }
.gs-rt-c-muted  { color:var(--gs-text-muted); }
.gs-rt-bg-accent, .gs-rt-bg-teal {

  color:#0e1611 !important; padding:0.04em 0.32em; border-radius:0.22em; font-weight:600;
  -webkit-box-decoration-break:clone; box-decoration-break:clone;
}
.gs-rt-bg-accent { background:var(--gs-accent); }
.gs-rt-bg-teal   { background:var(--gs-teal); }

.gs-rt-bg-accent-pill, .gs-rt-bg-teal-pill {
  color:#0e1611 !important; padding:0.06em 0.5em; border-radius:1em; font-weight:600;
  -webkit-box-decoration-break:clone; box-decoration-break:clone;
}
.gs-rt-bg-accent-pill { background:var(--gs-accent); }
.gs-rt-bg-teal-pill   { background:var(--gs-teal); }

.gs-surround { border-radius:16px; padding:clamp(20px,3vw,36px); }
.gs-surround-card    { background:var(--gs-card); border:1px solid var(--gs-border-soft,rgba(255,255,255,.1)); -webkit-backdrop-filter:blur(8px); backdrop-filter:blur(8px); }
.gs-surround-soft    { background:var(--gs-accent-soft,rgba(200,255,0,.06)); border:1px solid var(--gs-accent-dim,rgba(200,255,0,.16)); }
.gs-surround-emerald { background:var(--gs-emerald-deep,#0e3122); border:1px solid rgba(78,205,196,.22); }
.gs-surround-outline { border:1px solid var(--gs-border,rgba(255,255,255,.14)); }
.gs-pad-snug  { padding:clamp(12px,2vw,20px); }
.gs-pad-roomy { padding:clamp(30px,4.5vw,56px); }

.gs-textscale-sm { font-size:0.9em; }
.gs-textscale-lg { font-size:1.14em; }
.gs-textscale-xl { font-size:1.3em; }

.gs-sec-spt-sm { margin-top:clamp(24px,4vw,48px); }
.gs-sec-spt-md { margin-top:clamp(48px,7vw,96px); }
.gs-sec-spt-lg { margin-top:clamp(80px,11vw,160px); }
.gs-sec-spb-sm { margin-bottom:clamp(24px,4vw,48px); }
.gs-sec-spb-md { margin-bottom:clamp(48px,7vw,96px); }
.gs-sec-spb-lg { margin-bottom:clamp(80px,11vw,160px); }
.gs-sec-surface-panel   { background:#1c1c1c; }
.gs-sec-surface-emerald { background:linear-gradient(180deg,#0e3122,#0b2419); }
.gs-sec-surface-deep    { background:#0a0a0a; }

.gs-sec-accent-teal {
  --gs-accent: var(--gs-teal); --gs-accent-dim: rgba(78,205,196,0.10);
  --gs-accent-soft: rgba(78,205,196,0.05); --gs-accent-glow: rgba(78,205,196,0.22); --gs-accent-mid: rgba(78,205,196,0.40);
}
.kicker { font-size:clamp(.75rem,.9vw,.9rem); font-weight:700; letter-spacing:.08em; text-transform:uppercase; color:var(--gs-accent); }
.lead { font-size:clamp(1.05rem,1.6vw,1.35rem); color:var(--gs-text-muted); max-width:60ch; }
.muted { color:var(--gs-text-muted); }
.faint { color:var(--gs-text-faint); }

.wrap { max-width:var(--gs-maxw); margin:0 auto; padding-inline:var(--gs-gutter); }
.section { padding-block:var(--gs-section-space); position:relative; }

.consultancy-page{position:relative;isolation:isolate;background:var(--gs-bg)}
.consultancy-tide{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;background:radial-gradient(ellipse at 72% 68%,rgba(58,140,100,.06),transparent 58%),var(--gs-bg)}
.consultancy-tide.live{background:var(--gs-bg)}
.consultancy-block{position:relative;z-index:1}
.consultancy-block .gs-blk>section{background:transparent}
#gs-blk-consultancy-decide>section,.consultancy-block>.band-light{background:var(--gs-light-bg)}

.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-layer-list,.b-compose-head,.b-bridge-intro,.b-cases-intro,.b-invite-inner,.b-pc-card,.b-compose-problem,.b-compose-answer,.b-layer-slab){--consultancy-glass-blur:16px;background-color:rgba(18,18,18,.55);-webkit-backdrop-filter:blur(var(--consultancy-glass-blur)) saturate(140%);backdrop-filter:blur(var(--consultancy-glass-blur)) saturate(140%)}
.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-layer-list,.b-compose-head,.b-bridge-intro,.b-cases-intro,.b-invite-inner){border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 1px 0 rgba(255,255,255,.06);border-radius:var(--gs-card-radius)}
.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-layer-list,.b-compose-head,.b-bridge-intro,.b-cases-intro){display:block;width:-moz-fit-content;width:fit-content;max-width:100%;box-sizing:border-box;padding:clamp(20px,2.4vw,32px)}
.consultancy-block .b-pc-head.center{margin-inline:auto}
.consultancy-block .b-layer-intro{margin-bottom:clamp(24px,3vw,40px)}
.consultancy-block .b-cases-intro>:first-child,.consultancy-block .b-layer-intro>:first-child,.consultancy-block .b-bridge-intro>:first-child{margin-top:0}
.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-compose-head,.b-bridge-intro,.b-cases-intro)>:last-child{margin-bottom:0}
.consultancy-block .b-bridge-intro{margin-bottom:clamp(20px,3vw,32px)}
.consultancy-block .b-invite-inner{max-width:min(820px,calc(100% - 2 * var(--gs-gutter)));padding:clamp(20px,2.4vw,32px)}
.consultancy-block :is(.b-compose-problem.is-on,.b-compose-tile.is-on,.b-compose-picked li){background-color:rgba(18,18,18,.55);background-image:linear-gradient(rgba(200,255,0,.08),rgba(200,255,0,.08));border-color:var(--gs-lime)}
.consultancy-block .b-invite-aurora{display:none}
@supports not (((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) or (-webkit-backdrop-filter:blur(1px))){.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-layer-list,.b-compose-head,.b-bridge-intro,.b-cases-intro,.b-invite-inner,.b-pc-card,.b-compose-problem,.b-compose-answer,.b-layer-slab){background-color:rgba(18,18,18,.85)}}
@media(max-width:640px){.consultancy-block :is(.b-pc-head,.b-layer-intro,.b-layer-list,.b-compose-head,.b-bridge-intro,.b-cases-intro,.b-invite-inner,.b-pc-card,.b-compose-problem,.b-compose-answer,.b-layer-slab){--consultancy-glass-blur:12px}}
.consultancy-block .kicker::after,.consultancy-block .b-logos-eyebrow::after{content:"";display:block;width:42px;height:1px;margin-top:10px;background:currentColor;transform:scaleX(0);transform-origin:left;transition:transform .6s var(--gs-ease)}
.consultancy-block .center .kicker::after,.consultancy-block .b-invite-inner .kicker::after,.consultancy-block .b-invite-card .kicker::after{margin-inline:auto}
.consultancy-block.is-in .kicker::after,.consultancy-block.is-in .b-logos-eyebrow::after{transform:scaleX(1)}
.consultancy-ready .consultancy-block:not(.is-in) .gs-blk>section>.wrap{opacity:0;transform:translateY(18px)}
.consultancy-block .gs-blk>section>.wrap{transition:opacity .65s var(--gs-ease),transform .65s var(--gs-ease)}
.consultancy-block .b-pc-card,.consultancy-block .b-layer-slab{translate:0 var(--consultancy-parallax,0px)}
#gs-blk-consultancy-logos .b-logos-viewport{-webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}
#gs-blk-consultancy-capabilities .b-pc-head{margin-bottom:clamp(32px,5vw,56px)}
@media(prefers-reduced-motion:reduce){.consultancy-block .gs-blk>section>.wrap{opacity:1!important;transform:none!important;transition:none!important}.consultancy-block .kicker::after,.consultancy-block .b-logos-eyebrow::after{transform:none;transition:none}.consultancy-block .b-pc-card,.consultancy-block .b-layer-slab{translate:none}}
@media print{.consultancy-tide{display:none}.consultancy-page{background:white}}
:is(#gs-blk-consultancy-capabilities,#gs-blk-consultancy-method,#gs-blk-consultancy-compose,#gs-blk-consultancy-bridge,#gs-blk-consultancy-cases,#gs-blk-consultancy-decide,#gs-blk-consultancy-invite)>section{padding-block:var(--gs-consultancy-section-space,96px)}
@media(max-width:640px){:is(#gs-blk-consultancy-capabilities,#gs-blk-consultancy-method,#gs-blk-consultancy-compose,#gs-blk-consultancy-bridge,#gs-blk-consultancy-cases,#gs-blk-consultancy-decide,#gs-blk-consultancy-invite)>section{--gs-consultancy-section-space:64px}}
.gs-rhythm h1{font-size:clamp(2.7rem,6vw,4.5rem);font-weight:800;line-height:1.04;letter-spacing:-.035em}
.gs-rhythm h2,.gs-rhythm .h2{font-size:clamp(2rem,4vw,2.75rem);font-weight:800;line-height:1.08;letter-spacing:-.025em}
.gs-rhythm .lead{max-width:62ch;line-height:1.7}
.gs-feature-panel{border-radius:var(--gs-feature-radius)}
.band-light{--gs-text:var(--gs-bg);--gs-text-muted:var(--gs-light-muted);--gs-text-faint:var(--gs-light-faint);--gs-accent:var(--gs-emerald);--gs-accent-dim:var(--gs-emerald-wash);--gs-accent-soft:var(--gs-emerald-wash);--gs-accent-mid:var(--gs-border);--gs-border-soft:rgba(18,18,18,.18);--gs-border:rgba(27,80,57,.3);--gs-border-strong:rgba(27,80,57,.5);--gs-card:rgba(255,255,255,.7);--gs-card-hover:#fff;background:var(--gs-light-bg);color:var(--gs-text)}
.band-light .accent,.band-light .kicker{color:var(--gs-emerald)}
.band-light a:focus-visible,.band-light button:focus-visible,.band-light input:focus-visible{outline-color:var(--gs-emerald)}
.section--tight { padding-block:clamp(48px,7vh,90px); }
.grid { display:grid; grid-gap:clamp(18px,2.4vw,32px); gap:clamp(18px,2.4vw,32px); }
.cols-2 { grid-template-columns:repeat(2,1fr); }
.cols-3 { grid-template-columns:repeat(3,1fr); }
.cols-4 { grid-template-columns:repeat(4,1fr); }
@media (max-width:900px){ .cols-2,.cols-3,.cols-4 { grid-template-columns:1fr; } }
.center { text-align:center; } .center .lead { margin-inline:auto; }

.btn { display:inline-flex; align-items:center; justify-content:center; gap:.6em; min-height:44px; padding:.85em 1.6em; border-radius:100px;
  font-weight:700; font-size:.95rem; letter-spacing:.01em; cursor:pointer; border:1px solid transparent;
  transition:transform var(--gs-dur) var(--gs-ease), background var(--gs-dur), color var(--gs-dur), border-color var(--gs-dur); }
.btn:hover { transform:translateY(-2px); }
.btn--primary { background:var(--gs-accent); color:#0e1611; }
.btn--primary:hover { box-shadow:0 10px 40px -10px var(--gs-accent-glow); }
.btn--ghost { border-color:var(--gs-text); color:var(--gs-text); background:transparent; }
.btn--ghost:hover { border-color:var(--gs-accent-mid); color:var(--gs-accent); background:var(--gs-accent-dim); }

.card { background:var(--gs-card); border:1px solid var(--gs-border-soft); border-radius:var(--gs-card-radius);
  padding:clamp(22px,2.6vw,34px); -webkit-backdrop-filter:blur(8px); backdrop-filter:blur(8px);
  transition:transform var(--gs-dur) var(--gs-ease), border-color var(--gs-dur), background var(--gs-dur); }
.card:hover { transform:translateY(-4px); border-color:var(--gs-border-strong); background:var(--gs-card-hover); }
.card .num { font-size:.78rem; font-weight:700; letter-spacing:.2em; color:var(--gs-accent); }

.site-header { position:fixed; inset:0 0 auto 0; z-index:50; display:flex; align-items:center; justify-content:space-between;
  padding:18px var(--gs-gutter); transition:background var(--gs-dur), padding var(--gs-dur), -webkit-backdrop-filter var(--gs-dur); transition:background var(--gs-dur), backdrop-filter var(--gs-dur), padding var(--gs-dur); transition:background var(--gs-dur), backdrop-filter var(--gs-dur), padding var(--gs-dur), -webkit-backdrop-filter var(--gs-dur); }
.site-header.scrolled { background:rgba(20,23,20,0.72); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px); padding-block:12px; border-bottom:1px solid var(--gs-border-soft); }
.site-header .logo img { width:150px; }
.nav { display:flex; align-items:center; gap:clamp(14px,2vw,30px); }
.nav a.link { font-size:.85rem; font-weight:600; color:var(--gs-text-muted); position:relative; transition:color var(--gs-dur); }
.nav a.link:hover, .nav a.link[aria-current="page"] { color:var(--gs-text); }
.nav a.link::after { content:''; position:absolute; left:0; bottom:-5px; height:2px; width:0; background:var(--gs-accent); transition:width var(--gs-dur) var(--gs-ease); }
.nav a.link:hover::after, .nav a.link[aria-current="page"]::after { width:100%; }
.nav .cta { padding:.6em 1.2em; border:1px solid var(--gs-accent-mid); border-radius:100px; color:var(--gs-text); font-size:.82rem; font-weight:700;
  background:var(--gs-accent-soft); transition:all var(--gs-dur); }
.nav .cta:hover { background:var(--gs-accent); color:#0e1611; }

.nav-toggle { display:none; flex-direction:column; align-items:center; justify-content:center; gap:5px;
  width:44px; height:44px; padding:0; background:none; border:0; cursor:pointer; position:relative; z-index:60;
  touch-action:manipulation; -webkit-tap-highlight-color:transparent; }
.nav-toggle span { display:block; width:24px; height:2px; background:var(--gs-text); border-radius:2px;
  transition:transform var(--gs-dur) var(--gs-ease), opacity var(--gs-dur) var(--gs-ease), background var(--gs-dur); }
.nav.open .nav-toggle span:nth-child(1){ transform:translateY(7px) rotate(45deg); background:var(--gs-accent); }
.nav.open .nav-toggle span:nth-child(2){ opacity:0; }
.nav.open .nav-toggle span:nth-child(3){ transform:translateY(-7px) rotate(-45deg); background:var(--gs-accent); }
body.nav-locked { overflow:hidden; }

.nav-links { display:flex; align-items:center; gap:clamp(14px,2vw,30px); }

@media (max-width:860px){
  .nav { gap:0; }
  .nav-toggle { display:flex; }

  .site-header.scrolled { backdrop-filter:none; -webkit-backdrop-filter:none; background:rgba(18,20,18,0.94); }
  .nav-links {
    position:fixed; inset:0; z-index:55;
    display:flex; flex-direction:column; align-items:center; justify-content:safe center; gap:2px;
    overflow-y:auto; -webkit-overflow-scrolling:touch;
    background:rgba(10,12,10,0.975); backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px);
    padding:88px 24px 44px; text-align:center;
    opacity:0; visibility:hidden; transform:translateY(-8px);
    transition:opacity .42s var(--gs-ease), transform .42s var(--gs-ease), visibility .42s;
  }
  .nav.open .nav-links { opacity:1; visibility:visible; transform:none; }
  .nav-links .link {
    display:block; font-size:1.5rem; font-weight:800; letter-spacing:-0.01em; color:var(--gs-text);
    padding:13px 0; opacity:1; transform:none;
  }
  .nav-links .link::after { display:none; }
  .nav-links .link:hover, .nav-links .link[aria-current="page"] { color:var(--gs-accent); }
  .nav-links .cta {
    display:inline-flex; margin-top:24px; font-size:.95rem; padding:.95em 1.9em; opacity:1; transform:none;
  }
  @media (prefers-reduced-motion: no-preference){
    .nav.open .nav-links .link { opacity:0; transform:translateY(14px); animation:gsNavIn .5s var(--gs-ease) forwards; }
    .nav.open .nav-links .link:nth-child(1){ animation-delay:.05s }
    .nav.open .nav-links .link:nth-child(2){ animation-delay:.10s }
    .nav.open .nav-links .link:nth-child(3){ animation-delay:.15s }
    .nav.open .nav-links .link:nth-child(4){ animation-delay:.20s }
    .nav.open .nav-links .link:nth-child(5){ animation-delay:.25s }
    .nav.open .nav-links .link:nth-child(6){ animation-delay:.30s }
    .nav.open .nav-links .link:nth-child(7){ animation-delay:.35s }
    .nav.open .nav-links .cta { opacity:0; transform:translateY(14px); animation:gsNavIn .5s var(--gs-ease) .4s forwards; }
  }
}
@keyframes gsNavIn { to { opacity:1; transform:none; } }

.site-footer { position:relative; padding:clamp(64px,9vh,120px) var(--gs-gutter) 48px; text-align:center; overflow:hidden; border-top:1px solid var(--gs-border-soft); }
.site-footer .foot-wave { position:absolute; right:-40px; bottom:-40px; width:min(440px,60vw); opacity:.5; pointer-events:none; }
.site-footer .logo { max-width:130px; margin:0 auto 14px; opacity:.8; }
.site-footer .logo img { width:100%; height:auto; display:block; }
.site-footer .tagline { font-weight:700; letter-spacing:.04em; }
.site-footer .foot-links { display:flex; gap:22px; justify-content:center; flex-wrap:wrap; margin:20px 0; }
.site-footer .foot-links a { font-size:.82rem; color:var(--gs-text-muted); transition:color var(--gs-dur); }
